import { createPlayerError } from "../../core/errors.js";

type RemotePlaybackLike = {
  watchAvailability?(callback: (available: boolean) => void): Promise<number>;
  prompt(): Promise<void>;
};

type MediaWithRemote = HTMLMediaElement & {
  readonly remote?: RemotePlaybackLike;
};

/** Returns true when the browser exposes the Remote Playback API. */
export function canAirPlay(media: HTMLMediaElement): boolean {
  return (media as MediaWithRemote).remote !== undefined;
}

/** Opens the platform remote-playback picker (AirPlay, Cast, etc.). */
export async function showAirPlayPicker(media: HTMLMediaElement): Promise<void> {
  const remote = (media as MediaWithRemote).remote;

  if (remote === undefined) {
    throw createPlayerError("Remote playback is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  await remote.prompt();
}
